WITH cleaned AS (SELECT *, GREATEST(quantity, unit_price) AS greatest_quantity_unit_price FROM order_items WHERE product_id IS NOT NULL AND unit_price BETWEEN 220 AND 340) SELECT *, AVG(unit_price) OVER (PARTITION BY product_id ORDER BY greatest_quantity_unit_price, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS unit_price_avg_6_prior, NTILE(5) OVER (PARTITION BY product_id ORDER BY quantity DESC, id) AS quantity_bucket FROM cleaned;
